  FT["PH-H2233"] = {"id":"PH-H2233","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2503_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Aborlan市","en":"An Act Creating Certain Barrios in the Municipality of Aborlan, Province of Palawan","orig":"An Act Creating Certain Barrios in the Municipality of Aborlan, Province of Palawan","vi":"Đạo luật thành lập các Barrio tại Đô thị Aborlan, Tỉnh Palawan","th":"พระราชบัญญัติจัดตั้งบาริโอหลายแห่ง ในเทศบาล Aborlan จังหวัด Palawan","id":"Undang-Undang membentuk beberapa Barrio di Kotamadya Aborlan, Provinsi Palawan","ms":"Akta menubuhkan beberapa Barrio di Perbandaran Aborlan, Wilayah Palawan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2503","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2503_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2233-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Tinagong-dagat, Apoaporawan and Malatgao in the Municipality of Aborlan, Province of Palawan, are converted into barrios of said municipality to be known as the barrios of Tinagong-dagat, Sandoval and Malatgao, respectively."}},{"id":"PH-H2233-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2234"] = {"id":"PH-H2234","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2504_1959.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":"在苏里高省设立若干村社的法案","en":"An Act Creating Certain Barrios in the Province of Surigao","orig":"An Act Creating Certain Barrios in the Province of Surigao","vi":"Đạo luật thành lập các Barrio tại Tỉnh Surigao","th":"พระราชบัญญัติจัดตั้งบาริโอหลายแห่ง ในจังหวัด Surigao","id":"Undang-Undang membentuk beberapa Barrio di Provinsi Surigao","ms":"Akta menubuhkan beberapa Barrio di Wilayah Surigao"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2504","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2504_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2234-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Bognan, Mone, Luha, Tumanan, Sta. Cruz, Sute, Tabon and Caguyao in the Municipality of Bislig, province of Surigao, are converted into barrios of said municipality to be known as the barrios of Bognan, Mone, Luha, Tumanan, Sta. Cruz, Sute, Tabon and Caguyao, respectively."}},{"id":"PH-H2234-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sitios of Lahi, Hayangabon, Cagdianao, Cabugo and Sapa in the Municipality of Claver, same province, are converted into barrios of said municipality to be known as the barrios of Lahi, Hayangabon, Cagdianao, Cabugo and Sapa, respectively."}},{"id":"PH-H2234-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sitio of Balibadon in the Municipality of Cortes, same province, is converted into a barrio of said municipality to be known as the barrio of Balibadon."}},{"id":"PH-H2234-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The sitios of Caman-onan, Lahi, Cambo-ayon and Anibongan in the Municipality of Gigaquit, same province, are converted into barrios of said municipality to be known as the barrios of Caman-onan, Lahi, Cambo-ayon and Anibongan, respectively."}},{"id":"PH-H2234-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The sitios of Cambatong and Tagasaka in the Municipality of Hinatuan, same province, are converted into barrios of said municipality to be known as the barrios of Cambatong and Tagasaka, respectively."}},{"id":"PH-H2234-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The sitios of Cabacungan, Unidad, Kinayan, Barobo, Anibungan, Diatagon, Javier, San Vicente, Amaga, Cangbagang and Bahi in the Municipality of Liangan, same province, are converted into barrios of said municipality to be known as the barrios of Cabacungan, Unidad, Kinayan, Barobo, Anibungan, Diatagon, Javier, San Vicente, Amaga, Cangbagang and Bahi, respectively."}},{"id":"PH-H2234-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The sitio of Cabiton-an in the Municipality of Loreto, same province, is converted into a barrio of said municipality to be known as the barrio of Magsaysay."}},{"id":"PH-H2234-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The sitios of San Jose, Dayano and Ombong in the Municipality of Mainit, same province, are converted into barrios of said municipality to be known as the barrios of San Jose, Dayano and Ombong, respectively."}},{"id":"PH-H2234-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The sitios of Cagtenae, Cawayan, Hanagdong and Carihatag in the Municipality of Malimono, same province, are converted into barrios of said municipality to be known as the barrios of Cagtenae, Cayawan, Hanagdong and Carihatag, respectively."}},{"id":"PH-H2234-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The sitio of Bito-on in the Municipality of Numacia, same province, is converted into a barrio of said municipality to be known as the barrio of Bito-on."}},{"id":"PH-H2234-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The sitios of Garcia, Magsaysay and Coboy in the Municipality of Sapao, same province, are converted into barrios of said municipality to be known as the barrios of Garcia, Magsaysay and San Juan, respectively."}},{"id":"PH-H2234-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The sitios of Poctoy and Mayag in the Municipality of Surigao, same province, are converted into barrios of said municipality to be known as the barrios of Poctoy and Mayag, respectively."}},{"id":"PH-H2234-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The sitios of Libas Gua, Barras, Layog, Jubang, Umbay, Carromata, Kinabigtasan, Bangsud, Ciagao, Maitum, Cayale, Bajao and Dayo-an in the Municipality of Tago, same province, are converted into barrios of said municipality to be known as the barrios of Libas Gua, Barras, Layog, Jubang, Umbay, Carromata, Kinabigtasan, Bangsud, Ciagao, Maitum, Cayale, Bajao and Dayo-an, respectively."}},{"id":"PH-H2234-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating Certain Barrios in the Province of Surigao","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
