  FT["PH-H2252"] = {"id":"PH-H2252","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2523_1959.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"在苏里高省设立若干村社的法案","en":"An Act Creating Certain Barrios in the Province of Surigao","orig":"An Act Creating Certain Barrios in the Province of Surigao","vi":"Đạo luật thành lập các Barrio tại Tỉnh Surigao","th":"พระราชบัญญัติจัดตั้งบาริโอหลายแห่ง ในจังหวัด Surigao","id":"Undang-Undang membentuk beberapa Barrio di Provinsi Surigao","ms":"Akta menubuhkan beberapa Barrio di Wilayah Surigao"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2523","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2523_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2252-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Amontay, Macopa and Magtanghali in the Municipality of Anao-aon, Province of Surigao, are converted into barrios of said municipality to be known as the barrios of Amontay, Macopa and Magtangali, respectively."}},{"id":"PH-H2252-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sitios of Tawagan, Panaosawon, Cabogo, Unidad, Lactudan, Pagbahanan and Salimbabayog in the Municipality of Cagwait, Province of Surigao, are converted into barrios of said municipality to be known as the barrios of Tawagan, Panaosawon, Cabogo, Unidad, Lactudan, Palhi, Pagbahanan and Bitaugan West, respectively."}},{"id":"PH-H2252-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sitio of Cabawan in the Municipality of Dapa, Province of Surigao, is converted into a barrio of said municipality to be known as the barrio of Cabawa."}},{"id":"PH-H2252-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The sitios of Tagbina, Port Lamon, Dugmanon, Sasa, Manambia, Biga-an, Maglambing and Talisay in the Municipality of Hintuan, Province of Surigao, are converted into barrios of said municipality to be known as the barrios of Tagbina, Port Lamon, Dugmanon, Sasa, Manambia, Biga-an, Maglambing and Talisay, respectively."}},{"id":"PH-H2252-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The sitios of Bungan, Salvacion, Mandus and Sabang in the Municipality of Lingig, Province of Surigao, are converted into barrios of said municipality to be known as the barrios of Bungan, Salvacion, Mandus and Sabang, respectively."}},{"id":"PH-H2252-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The sitios of San Pedro, Alipao, Matinao, Tapian, Mansayao, Binga, San Francisco, Cantugas and Mainit in the Municipality of Mainit, Province of Surigao, are converted into barrios of said municipality to be known as the barrios of San Pedro, Alipao, Matinao, Tapian, Mansayao, Binga, San Francisco, Cantugas and Mainit, respectively."}},{"id":"PH-H2252-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The sitios of Cabongbongan, Cajuyao, Sabang, Punta Bilar, Nabago, Togbongo, Cagutsan, Balibayon, Orok, Cagniog, Mabuhay, Mabua, Alang-alang, Auora and Baybay in the Municipality of Surigao, Province of Surigao, are converted into barrios of said municipality to be known as the barrios of Cabongbongan, Cajuyao, Sabang, Punta Bilar, Nabago, Togbongan, Cagutsan, Balibayon, Orok, Cagniog, Mabuhay, Mabua Alang-alang, Aurora and Baybay, respectively."}},{"id":"PH-H2252-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The sitios of Awasan Norte, Buanbuan, Cagbaoto, Unahan and Abaga in the Municipality of Tago, Province of Surigao, are converted into barrios of said municipality to be known as the barrios of Awasan Norte, Buanbuan, Cagbaoto, Unahan and San Roque, respectively."}},{"id":"PH-H2252-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The sitios of Rosario Tabontabon, Sotil and Carmen in the Municipality of Tandag, Province of Surigao, are converted into barrios of said municipality to be known as the barrios of Rosario, Tabontabon, Sotil and Carmen, respectively."}},{"id":"PH-H2252-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating Certain Barrios in the Province of Surigao","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2253"] = {"id":"PH-H2253","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2524_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Malilipot市","en":"An Act Converting the Sitio of Calbayog, Municipality of Malilipot, Province of Albay, into a Barrio of Said Municipality","orig":"An Act Converting the Sitio of Calbayog, Municipality of Malilipot, Province of Albay, into a Barrio of Said Municipality","vi":"Đạo luật chuyển đổi Sitio Calbayog tại Thị trấn Malilipot, Tỉnh Albay thành Barrio của thị trấn nói trên","th":"พระราชบัญญัติเปลี่ยนสถานะซิติโอ Calbayog ในเทศบาล Malilipot จังหวัด Albay เป็น บาริโอของเทศบาลดังกล่าว","id":"Undang-Undang mengubah Sitio Calbayog di Kotamadya Malilipot, Provinsi Albay menjadi Barrio dari kotamadya tersebut","ms":"Akta menukar status Sitio Calbayog di Perbandaran Malilipot, Wilayah Albay kepada Barrio daripada perbandaran tersebut"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2524","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2524_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2253-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Calbayog, Municipality of Malilipot, Province of Albay, is converted into a barrio of said municipality to be known as the barrio of Calbayog."}},{"id":"PH-H2253-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
